.screen {
  text-align: center;
  background: #333;
  color: white;
  letter-spacing: 0.3em;
  padding: 0.5rem;
  border-radius: 4px;
  margin-bottom: 1rem;
}

.seat-map {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.seat-row {
  display: grid;
  grid-template-columns:
    2.5em
    repeat(4, 2.4em)
    4.8em
    repeat(16, 2.4em)
    4.8em
    repeat(4, 2.4em)
    2.5em;
  align-items: center;
  grid-column: 1;
}

.row-label {
  text-align: center;
  font-size: 0.85em;
  color: #555;
  grid-column: 1;
}

.seat-row > .row-label:last-of-type {
  grid-column: 28;
}

.aisle {
  content: '';
}

.seat,
.couch {
  height: 2em;
  border: none;
  border-radius: 4px;
  font-size: 0.75em;
  cursor: pointer;
  color: white;
  margin: 1px;
  padding: 0;
}

.seat:disabled,
.couch:disabled {
  cursor: default;
}

.state-available {
  background-color: #2e7d32;
}

.state-selected {
  background-color: #f9a825;
}

.state-unavailable {
  background-color: #c62828;
  cursor: default;
}

.state-accessible {
  background-color: #1565c0;
}

