    if (this.seatState(cell) === 'unavailable') return;
    this.toggle.emit([cell.id]);
  }

  onCouchClick(cell: CouchCellVm): void {
    if (this.couchState(cell) === 'unavailable') return;
    this.toggle.emit([cell.id1, cell.id2]);
