// Minimal CDP driver using only Node built-ins (no playwright/puppeteer dependency).
// Usage: node cdp.js <command.json>
// command.json: { "actions": [ {type:"nav",url}, {type:"eval",expr}, {type:"click",selector}, {type:"screenshot",path}, {type:"wait",ms} ] }

const fs = require('fs');

async function main() {
  const versionRes = await fetch('http://127.0.0.1:9222/json/version');
  const { webSocketDebuggerUrl } = await versionRes.json();

  // Create a new tab via HTTP endpoint
  const newTabRes = await fetch('http://127.0.0.1:9222/json/new?about:blank', { method: 'PUT' });
  const tab = await newTabRes.json();
  const wsUrl = tab.webSocketDebuggerUrl;

  const ws = new WebSocket(wsUrl);
  await new Promise((resolve, reject) => {
    ws.addEventListener('open', resolve, { once: true });
    ws.addEventListener('error', reject, { once: true });
  });

  let msgId = 1;
  const pending = new Map();
  const consoleMessages = [];
  const pageErrors = [];

  ws.addEventListener('message', (ev) => {
    const msg = JSON.parse(ev.data);
    if (msg.id && pending.has(msg.id)) {
      const { resolve, reject } = pending.get(msg.id);
      pending.delete(msg.id);
      if (msg.error) reject(new Error(JSON.stringify(msg.error)));
      else resolve(msg.result);
    } else if (msg.method === 'Runtime.consoleAPICalled') {
      const args = (msg.params.args || []).map((a) => a.value ?? a.description ?? '').join(' ');
      consoleMessages.push(`[${msg.params.type}] ${args}`);
    } else if (msg.method === 'Runtime.exceptionThrown') {
      pageErrors.push(JSON.stringify(msg.params.exceptionDetails.exception?.description || msg.params.exceptionDetails));
    }
  });

  function send(method, params = {}) {
    const id = msgId++;
    return new Promise((resolve, reject) => {
      pending.set(id, { resolve, reject });
      ws.send(JSON.stringify({ id, method, params }));
    });
  }

  await send('Page.enable');
  await send('Runtime.enable');
  await send('Network.enable');

  const script = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
  const results = [];

  for (const action of script.actions) {
    if (action.type === 'nav') {
      await send('Page.navigate', { url: action.url });
      await new Promise((r) => setTimeout(r, action.wait ?? 1500));
      results.push({ action, ok: true });
    } else if (action.type === 'wait') {
      await new Promise((r) => setTimeout(r, action.ms));
      results.push({ action, ok: true });
    } else if (action.type === 'eval') {
      const r = await send('Runtime.evaluate', { expression: action.expr, returnByValue: true, awaitPromise: true });
      results.push({ action, result: r.result?.value, exceptionDetails: r.exceptionDetails });
    } else if (action.type === 'screenshot') {
      const r = await send('Page.captureScreenshot', { format: 'png' });
      fs.writeFileSync(action.path, Buffer.from(r.data, 'base64'));
      results.push({ action, ok: true });
    }
  }

  console.log(JSON.stringify({ results, consoleMessages, pageErrors }, null, 2));
  ws.close();
  process.exit(0);
}

main().catch((e) => {
  console.error('DRIVER ERROR', e);
  process.exit(1);
});

